"""Dependency-free local operations console."""
from fastapi.responses import HTMLResponse


def dashboard() -> HTMLResponse:
    return HTMLResponse("""<!doctype html><html lang="en"><head><meta charset="utf-8"><meta name="viewport" content="width=device-width,initial-scale=1"><title>Verdict | Identity Screening</title><style>
:root{--ink:#172033;--sub:#68758a;--line:#e4e8ee;--canvas:#f5f7fa;--paper:#fff;--navy:#14213d;--violet:#6558d3;--mint:#1a9d78;--mintbg:#e7f7f1;--amber:#b56709;--amberbg:#fff5df;--rose:#ca3f52;--rosebg:#fff0f2;--blue:#3474c5;--bluebg:#ecf4ff}*{box-sizing:border-box}body{margin:0;background:var(--canvas);color:var(--ink);font:14px/1.45 Inter,ui-sans-serif,system-ui,-apple-system,"Segoe UI",sans-serif}.shell{max-width:1440px;margin:auto;padding:0 28px 42px}.top{height:72px;display:flex;align-items:center;justify-content:space-between}.brand{display:flex;gap:10px;align-items:center;font-size:17px;font-weight:800;letter-spacing:-.02em}.mark{width:32px;height:32px;display:grid;place-items:center;background:var(--navy);color:#fff;border-radius:9px}.muted{color:var(--sub);font-weight:600}.online{font-size:11px;font-weight:800;letter-spacing:.06em;color:#426253}.online i{display:inline-block;width:7px;height:7px;border-radius:50%;background:#2ab27b;margin-right:6px}.hero{border-radius:20px;background:linear-gradient(115deg,#182746,#203f68 64%,#315e85);color:#fff;padding:31px 34px;display:flex;align-items:end;justify-content:space-between;gap:20px;box-shadow:0 15px 35px #14213d24}.eyebrow,.step{font-size:11px;letter-spacing:.11em;text-transform:uppercase;font-weight:800}.eyebrow{color:#b9cff0}.step{color:var(--violet)}h1{font-size:30px;line-height:1.13;letter-spacing:-.035em;margin:7px 0}.hero p{max-width:630px;margin:0;color:#d4e0ef}.button{appearance:none;border:0;border-radius:9px;padding:10px 14px;font:700 13px inherit;cursor:pointer;transition:.16s transform}.button:hover{transform:translateY(-1px)}.ghost{background:#ffffff1f;color:#fff;border:1px solid #ffffff42}.primary{background:var(--navy);color:#fff;width:100%;margin-top:18px}.stats{display:grid;grid-template-columns:repeat(4,1fr);gap:14px;margin:18px 0}.stat,.card{background:var(--paper);border:1px solid var(--line);border-radius:15px}.stat{padding:17px 18px}.stat small{color:var(--sub);font-weight:650}.stat strong{font-size:25px;letter-spacing:-.035em;display:block;margin-top:5px}.alert strong{color:var(--amber)}.layout{display:grid;grid-template-columns:minmax(315px,.82fr) minmax(520px,1.6fr);gap:18px}.card{padding:22px}.head{display:flex;align-items:flex-start;justify-content:space-between;gap:12px;border-bottom:1px solid var(--line);padding-bottom:15px;margin-bottom:17px}h2{font-size:16px;letter-spacing:-.02em;margin:3px 0}p{font-size:13px;color:var(--sub);margin:4px 0}label{display:block;font-size:12px;font-weight:760;margin:16px 0 6px}input,select{width:100%;border:1px solid #dce2ea;border-radius:8px;background:#fff;color:var(--ink);padding:10px;font:inherit}input:focus,select:focus{outline:3px solid #6558d321;border-color:var(--violet)}.drop{border:1.5px dashed #b9c4d4;border-radius:11px;background:#fafbfd;padding:16px;text-align:center}.drop input{border:0;padding:0;width:auto;max-width:100%;background:transparent}.hint,.sub{font-size:11px;color:var(--sub);margin:6px 0}.row{display:grid;grid-template-columns:1fr 1fr;gap:11px}.option{display:flex;gap:7px;align-items:center;margin-top:14px;padding:9px 10px;border-radius:8px;background:#f7f8fb;color:var(--sub);font-size:11px}.option input{width:auto;margin:0}.message{min-height:20px;margin:10px 0 0;color:var(--sub);font-size:12px}.badge{display:inline-flex;align-items:center;border-radius:99px;padding:4px 8px;font-size:10px;line-height:1.1;font-weight:850;letter-spacing:.035em;background:var(--bluebg);color:var(--blue)}.amber{background:var(--amberbg);color:var(--amber)}.rose{background:var(--rosebg);color:var(--rose)}.mint{background:var(--mintbg);color:var(--mint)}.queue{display:grid;grid-template-columns:1.25fr .7fr .9fr auto;gap:13px;align-items:center;border-top:1px solid var(--line);padding:14px 4px}.file{font-weight:760;overflow:hidden;text-overflow:ellipsis;white-space:nowrap}.actions{display:flex;gap:5px;flex-wrap:wrap;justify-content:end}.actions button{border:1px solid var(--line);background:#fff;color:var(--ink);padding:6px 8px;border-radius:6px;font:700 11px inherit;cursor:pointer}.actions .reject{color:var(--rose);border-color:#f1cbd2}.actions .escalate{color:var(--amber);border-color:#f4d9ab}.empty{color:var(--sub);padding:24px 2px;text-align:center}.result{margin-top:11px;border:1px solid var(--line);border-radius:9px;background:#fbfcfe}.result summary{padding:11px;cursor:pointer;font-weight:700}.result pre{margin:0;border-top:1px solid var(--line);padding:12px;max-height:360px;overflow:auto;white-space:pre-wrap;word-break:break-word;color:#3f4d62;font-size:11px}.foot{display:flex;justify-content:space-between;gap:20px;padding:18px 2px;color:var(--sub);font-size:11px}@media(max-width:900px){.layout{grid-template-columns:1fr}.stats{grid-template-columns:1fr 1fr}.queue{grid-template-columns:1fr}.actions{justify-content:start}.hero{align-items:flex-start;flex-direction:column}}@media(max-width:540px){.shell{padding:0 14px 28px}.hero{padding:24px 21px}h1{font-size:25px}.stats,.row{grid-template-columns:1fr}.online{display:none}}
</style></head><body><main class="shell"><header class="top"><div class="brand"><span class="mark">V</span>Verdict <span class="muted">/ Identity Screening</span></div><span class="online"><i></i>LOCAL SYSTEM ONLINE</span></header><section class="hero"><div><div class="eyebrow">AI-Based Fake Identity &amp; Document Screening</div><h1>Know what needs a closer look.</h1><p>Screen identity documents for manipulation, reuse, identity inconsistencies and synthetic media—with a clear audit trail behind every decision.</p></div><button class="button ghost" id="refresh">Refresh workspace</button></section><section class="stats"><div class="stat"><small>Documents screened</small><strong id="total">—</strong></div><div class="stat alert"><small>Awaiting review</small><strong id="pending">—</strong></div><div class="stat"><small>Cleared by analysts</small><strong id="approved">—</strong></div><div class="stat"><small>Escalated or rejected</small><strong id="resolved">—</strong></div></section><section class="layout"><article class="card"><div class="head"><div><div class="step">New screening</div><h2>Submit documents</h2><p>Files are fingerprinted and added to local provenance.</p></div></div><form id="upload"><label>Document image or PDF</label><div class="drop"><input id="files" type="file" accept=".png,.jpg,.jpeg,.webp,.pdf,application/pdf" multiple><p class="hint">PNG, JPG, WEBP or PDF · up to five PDF pages</p></div><label>Or choose a document folder</label><input id="folder" type="file" accept=".png,.jpg,.jpeg,.webp,.pdf,application/pdf" multiple webkitdirectory directory><div class="row"><div><label>Case reference</label><input id="identity" maxlength="128" placeholder="Optional case ID"></div><div><label>Screening depth</label><select id="mode"><option value="fast" selected>Fast triage</option><option value="full">Full analysis</option></select></div></div><label>Separate live selfie <span class="muted">optional, single file only</span></label><input id="liveSelfie" type="file" accept=".png,.jpg,.jpeg,.webp"><label class="option"><input id="consent" type="checkbox" required> I am authorised to screen these documents.</label><button class="button primary" type="submit">Start screening</button></form><div id="uploadmsg" class="message"></div><div id="screenresults"></div></article><article class="card"><div class="head"><div><div class="step">Review workspace</div><h2>Cases needing attention</h2><p>Resolve a case only after reviewing its evidence.</p></div><span class="badge" id="queuecount">—</span></div><div class="row"><div><label style="margin-top:0">Analyst ID</label><input id="operator" maxlength="128" value="local-operator"></div><div><label style="margin-top:0">Decision note</label><input id="notes" maxlength="2000" placeholder="Optional audit note"></div></div><div id="queue"></div></article></section><footer class="foot"><span>Local deployment · Evidence-based screening, not legal verification.</span><span>Provenance · Audit trail · Human review</span></footer></main><script>
const $=id=>document.getElementById(id),esc=v=>{const e=document.createElement('span');e.textContent=String(v??'');return e.innerHTML};function pill(text){const value=String(text||'').toLowerCase(),type=value.includes('fake')?'rose':value.includes('manual')||value.includes('review')?'amber':value.includes('genuine')?'mint':'';return `<span class="badge ${type}">${esc(text)}</span>`}async function api(url,options){const r=await fetch(url,options),body=await r.json();if(!r.ok)throw Error(typeof body.detail==='string'?body.detail:'Request failed');return body}async function load(){try{const [summary,queue]=await Promise.all([api('/operations/overview'),api('/review-queue?limit=50')]);$('total').textContent=summary.total_screenings;$('pending').textContent=summary.pending_review;$('approved').textContent=summary.review_decisions.APPROVED||0;$('resolved').textContent=(summary.review_decisions.REJECTED||0)+(summary.review_decisions.ESCALATED||0);$('queuecount').textContent=`${queue.items.length} OPEN`;$('queue').innerHTML=queue.items.map(item=>`<div class="queue"><div><div class="file">${esc(item.filename)}</div><div class="sub">${esc(item.screening_id)} · ${esc(item.submitted_at)}</div></div><div>${pill(item.triage)}<div class="sub">Risk ${esc(item.risk_score)}</div></div><div class="sub">${esc((item.reasons||[]).join(', ')||'Evidence pending review')}</div><div class="actions"><button onclick="decide('${item.screening_id}','APPROVED')">Clear</button><button class="reject" onclick="decide('${item.screening_id}','REJECTED')">Reject</button><button class="escalate" onclick="decide('${item.screening_id}','ESCALATED')">Escalate</button></div></div>`).join('')||'<div class="empty">No cases currently require review.</div>'}catch(error){$('queue').innerHTML=`<div class="empty">Unable to load workspace: ${esc(error.message)}</div>`}}window.decide=async(id,decision)=>{try{const form=new FormData();form.append('decision',decision);form.append('notes',$('notes').value);await api(`/screen/${id}/review`,{method:'POST',headers:{'X-Operator-ID':$('operator').value||'local-operator'},body:form});$('notes').value='';load()}catch(error){alert(error.message)}};$('refresh').onclick=load;$('upload').addEventListener('submit',async event=>{event.preventDefault();const chosen=$('files').files.length?$('files').files:$('folder').files,live=$('liveSelfie').files[0];if(!chosen.length){$('uploadmsg').textContent='Choose at least one document image, PDF or folder.';return}if(live&&chosen.length!==1){$('uploadmsg').textContent='Use a separate live selfie with one document only.';return}$('uploadmsg').textContent='Screening documents and recording provenance…';const form=new FormData();form.append('analysis_mode',$('mode').value);if($('identity').value.trim())form.append('identity_key',$('identity').value.trim());try{let result;if(live){form.append('file',chosen[0],chosen[0].name);form.append('live_selfie',live,live.name);result={results:[await api('/screen',{method:'POST',body:form})]}}else{for(const file of chosen)form.append('files',file,file.name);result=await api('/screen/batch',{method:'POST',body:form})}$('uploadmsg').textContent=`Completed ${result.results.length} screening(s).`;$('screenresults').innerHTML=result.results.map(item=>`<details class="result"><summary>${pill(item.triage?.label||item.status)} ${esc(item.filename)} · risk ${esc(item.risk_score)}</summary><pre>${esc(JSON.stringify(item,null,2))}</pre></details>`).join('');load()}catch(error){$('uploadmsg').textContent=error.message}});load();
</script></body></html>""")
